{
  "гриб": "Аманита мушиария (Amanita muscaria) — красный мухомор",
  "состав": [
    {
      "вещество": "Мусцимол (4,5,6-тригидро-3-метилгепт-5-еновая кислота, GABA-аналог)",
      "содержание": "1–4 мг/г сухого веса (≈0,1–0,4 %)",
      "влияние": "Агонист GABA-A рецепторов, вызывает седацию, гипноз и лёгкое опьянение."
    },
    {
      "вещество": "Изотиновая кислота (ibotenic acid)",
      "содержание": "0,5–5 мг/г сухого веса (≈0,05–0,5 %)",
      "влияние": "Агонист NMDA-рецепторов; в высоких дозах проявляет нейротоксичность и может诱发 судороги."
    },
    {
      "вещество": "Мускариин (muscaryine)",
      "содержание": "1–10 мг/кг сухого веса (≈0,001–0,01 %)",
      "влияние": "Агонист мускариновых ацетилхолиновых рецепторов: брадикардия, гиперсаливация, мидриаз/миоз."
    },
    {
      "вещество": "Мускафлавины (muscaflavins, флавоноидные пигменты)",
      "содержание": "≈0,1–1 % сухого веса шляпки",
      "влияние": "Антиоксиданты и противовоспалительные агенты; придают характерный красно-оранжевый цвет."
    },
    {
      "вещество": "Эрговинин (эргот-алкалоид)",
      "содержание": "1–10 мг/кг сухого веса",
      "влияние": "Вазоконстриктор; при значимых дозах способен вызывать спазм сосудов и головную боль."
    },
    {
      "вещество": "Тритерпеноидные сапонины (мускарин, муцатинол и др.)",
      "содержание": "1–3 % сухого веса",
      "влияние": "Придают выраженный горький вкус; обладают слабым противовоспалительным и мурашиным (пенообразующим) действием."
    },
    {
      "вещество": "Полисахариды (β-глюканы, хитин)",
      "содержание": "10–30 % сухого веса",
      "влияние": "Структурный компонент клеточной стенки; модулируют иммунный ответ, снижают уровень холестерина в сыворотке."
    },
    {
      "вещество": "Белки и аминокислоты (в т. ч. глутамин, аспарагин)",
      "содержание": "3–8 % сухого веса",
      "влияние": "Обеспечивают пластический и энергетический обмен; свободный глутамин усиливает вкусовое (аминовое) восприятие."
    },
    {
      "вещество": "Биотин (витамин B7)",
      "содержание": "несколько мг/кг сухого веса шляпки",
      "влияние": "Кофактор карбоксилаз, необходим для метаболизма жирных кислот и глюкозы."
    },
    {
      "вещество": "Липиды (фосфолипиды, фитостеролы, в т. ч. stigmasterol)",
      "содержание": "2–5 % сухого веса",
      "влияние": "Составная часть мембран; фитостеролы конкурентно конкурируют с холестерином всасывания в кишечнике."
    }
  ]
}

{
  "гриб": "Amanita caesarea (цезарский гриб, мухомор Цезаря, царский гриб)",
  "состав": [
    {
      "вещество": "Белки (глютен, альбумин, глобулины)",
      "содержание": "≈ 2–5 % от свежего веса",
      "влияние": "Усваиваются как обычный пищевой белок, обеспечивая аминокислотный запас."
    },
    {
      "вещество": "Углеводы (глюкоза, мальтоза, трегалоза)",
      "содержание": "≈ 5–12 % от свежего веса",
      "влияние": "Поставляют энергию; трегалоза стабилизует клеточные мембраны."
    },
    {
      "вещество": "Инозит (циклогексгексаол)",
      "содержание": "неизвестно",
      "влияние": "Участвует в клеточной сигнализации и метаболизме фосфолипидов."
    },
    {
      "вещество": "Эргостерол (провитамин D₂)",
      "содержание": "неизвестно",
      "влияние": "После УФ-облучения превращается в витамин D, участвующий в обмене кальция."
    },
    {
      "вещество": "Аминокислоты (глутаминовая, аспарагиновая, аланин, треонин, серин)",
      "содержание": "неизвестно",
      "влияние": "Формируют характерный умами-вкус и участвуют в азотистом обмене."
    },
    {
      "вещество": "Тритерпеноиды (каезановая кислота, каезаренин)",
      "содержание": "неизвестно",
      "влияние": "Специфичны для вида; в пищевых дозах не дают выраженного токсического эффекта, но обладают лёгким горьковатым вкусом."
    },
    {
      "вещество": "Витамины группы B (тиамин B₁, рибофлавин B₂, ниацин B₃, B₅, B₆)",
      "содержание": "неизвестно",
      "влияние": "Кофакторы ферментов энергетического обмена и синтеза нуклеиновых кислот."
    },
    {
      "вещество": "Минеральные вещества (K, P, Ca, Mg, Fe, Zn)",
      "содержание": "≈ 0,5–1,5 % от свежего веса (в сумме)",
      "влияние": "Обеспечивают электролитный баланс, передачу нервных импульсов и кроветворение."
    },
    {
      "вещество": "Эрготионеин",
      "содержание": "неизвестно",
      "влияние": "Действует как антиоксидант, защищая клетки от окислительного стресса."
    },
    {
      "вещество": "Иботеновая кислота / мусцимолин (следы)",
      "содержание": "неизвестно (значительно ниже, чем у других Amanita)",
      "влияние": "В микродозах практически не влияют на ЦНС; при избытке мусцимолин активирует GABA-рецепторы."
    }
  ]
}
